// FinanceProfitSchema.js — FRONTEND schema: labels, formulas, remarks, click-throughs. Generated by gen-report.js from report.map (same folder).
// The numbers come from the backend twin app/api/mda4/reports/finance/profit/list/FinanceProfitSchema.js (same measure keys).
import { getApiRoutes } from '../../../AppRoutes/apiRoutesHandler';
import FinanceProfitActions from './logicControl/actionsRegistry';
const apiRoutes = getApiRoutes();

export const FinanceProfitSchema = {
  entity: 'simukopa_finance_profit',
  label: 'Profit and Risk',
  description: '',
  apiBase: apiRoutes.financeprofit?.base,
  moduleRole: 'view_reports',
  currency: 'KES',
  actionRegistry: FinanceProfitActions,

  groupBy: 'month',
  groupLabel: 'Month',
  groupByOptions: [{ key: 'month', label: 'Month' }, { key: 'day', label: 'Day' }, { key: 'year', label: 'Year' }],

  fields: [
    { key: 'interest_in', label: 'Interest Earned', from: 'payment_allocations.interest_amount', type: 'money' },
    { key: 'fees_in', label: 'Fees Earned', from: 'payment_allocations.fee_amount', type: 'money' },
    { key: 'penalty_in', label: 'Penalties Earned', from: 'payment_allocations.penalty_amount', type: 'money' },
    { key: 'commission', label: 'Commissions Paid', from: 'commissions.amount', type: 'money' },
    { key: 'late_balance', label: 'Overdue Balance', from: 'loan_installments.balance_amount', type: 'money' },
    { key: 'default_balance', label: 'Defaulted Balance', from: 'loans.balance_amount', type: 'money' },
    { key: 'income', label: 'Income Earned', calc: 'interest_in + fees_in + penalty_in', type: 'money' },
    { key: 'net', label: 'Net After Commissions', calc: 'income - commission', type: 'money' },
    { key: 'chg', label: 'Net vs Previous', calc: 'change(net)' },
  ],

  remarks: [
    { if: 'net < 0', tone: 'bad', title: 'Loss', say: '{label}: commissions of {commission} were more than the {income} earned.' },
    { if: 'late_balance > income', tone: 'bad', title: 'Risk above income', say: '{label}: {late_balance} is overdue, more than the {income} earned.' },
    { if: 'chg !== null && chg <= -20', tone: 'watch', title: 'Earnings fell', say: '{label}: net {net}, down {abs(chg)}% on {prev_label}.' },
    { if: 'true', tone: 'good', title: 'Healthy', say: '{income} earned, {net} net, {late_balance} overdue and {default_balance} defaulted.' },
  ],

  headline: '{label}: {income} earned, {net} after commissions[, {updown} {abs(chg)}% on {prev_label}].',
};
